import{_ as e,o as a,c as o,a0 as r}from"./chunks/framework.tsJrOMu2.js";const p=JSON.parse('{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"tools/index.md","filePath":"tools/index.md"}'),d={name:"tools/index.md"};function i(s,t,l,n,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h1><p>Agentrail provides a set of built-in tools through <code>@agentrail/capabilities</code>. Tools are registered on a profile and exposed to the agent at runtime.</p><h2 id="tool-categories" tabindex="-1">Tool categories <a class="header-anchor" href="#tool-categories" aria-label="Permalink to &quot;Tool categories&quot;">​</a></h2><h3 id="filesystem" tabindex="-1">Filesystem <a class="header-anchor" href="#filesystem" aria-label="Permalink to &quot;Filesystem&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><a href="./bash">Bash</a></td><td>Execute shell commands</td></tr><tr><td><a href="./read">Read</a></td><td>Read files from the local filesystem</td></tr><tr><td><a href="./write">Write</a></td><td>Write files to the local filesystem</td></tr><tr><td><a href="./edit">Edit</a></td><td>Exact string replacement in existing files</td></tr><tr><td><a href="./grep">Grep</a></td><td>Regex search powered by ripgrep</td></tr><tr><td><a href="./glob">Glob</a></td><td>Find files by glob pattern</td></tr></tbody></table><h3 id="web" tabindex="-1">Web <a class="header-anchor" href="#web" aria-label="Permalink to &quot;Web&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><a href="./web-fetch">WebFetch</a></td><td>Fetch a URL and return readable Markdown</td></tr><tr><td><a href="./web-search">WebSearch</a></td><td>Search the web via a provider adapter</td></tr></tbody></table><h3 id="interaction" tabindex="-1">Interaction <a class="header-anchor" href="#interaction" aria-label="Permalink to &quot;Interaction&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><a href="./ask-user-question">AskUserQuestion</a></td><td>Pause execution and ask the user a question</td></tr><tr><td><a href="./todo-write">TodoWrite</a></td><td>Maintain a structured task list for the session</td></tr><tr><td><a href="./sleep">Sleep</a></td><td>Pause execution for a bounded duration</td></tr></tbody></table><h3 id="sandbox-only" tabindex="-1">Sandbox-only <a class="header-anchor" href="#sandbox-only" aria-label="Permalink to &quot;Sandbox-only&quot;">​</a></h3><p>These tools are available only when the agent runs inside a Docker sandbox container (see <code>@agentrail/capabilities</code> sandboxed capability set).</p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><a href="./python">Python</a></td><td>Execute Python code inside the sandbox</td></tr><tr><td><a href="./browser-navigate">BrowserNavigate</a></td><td>Navigate the in-sandbox Chromium browser to a URL</td></tr><tr><td><a href="./browser-content">BrowserContent</a></td><td>Read the current browser page&#39;s visible text</td></tr><tr><td><a href="./browser-scroll">BrowserScroll</a></td><td>Scroll the current browser page or an element</td></tr><tr><td><a href="./browser-action">BrowserAction</a></td><td>Click, fill, select, hover, press, or evaluate JavaScript</td></tr></tbody></table><h3 id="orchestration" tabindex="-1">Orchestration <a class="header-anchor" href="#orchestration" aria-label="Permalink to &quot;Orchestration&quot;">​</a></h3><p>Orchestration tools are available when the multi-agent orchestration capability is enabled.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><a href="./spawn-agent">spawn_agent</a></td><td>Spawn a session-scoped orchestration sub-agent</td></tr><tr><td><a href="./close-agent">close_agent</a></td><td>Close a sub-agent and resolve dependent waits</td></tr><tr><td><a href="./send-input">send_input</a></td><td>Queue structured input for a sub-agent</td></tr><tr><td><a href="./wait-agent">wait_agent</a></td><td>Wait for one or more agents to satisfy a condition</td></tr></tbody></table><h2 id="additional-capability-tools" tabindex="-1">Additional capability tools <a class="header-anchor" href="#additional-capability-tools" aria-label="Permalink to &quot;Additional capability tools&quot;">​</a></h2><p>The following tools are provided by optional capability packages and documented inline:</p><ul><li><strong>KbList / KbRead / KbSearch</strong> — knowledge base tools from the <code>knowledge</code> capability</li><li><strong>Skill</strong> — skill delegation tool from the <code>skills</code> capability</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Several tools (<code>Bash</code>, <code>Read</code>, <code>Write</code>, <code>Edit</code>, and their sandbox counterparts) support a <code>checkPermissions</code> hook that evaluates the active <code>ToolPermissionPolicy</code> before execution. See the <a href="./../guides/tool-permissions">Tool Permissions Guide</a> for details.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../guides/add-tools">Add Tools</a></li><li><a href="./../guides/tool-permissions">Tool Permissions</a></li><li><a href="./../guides/use-capability-packages">Use Capability Packages</a></li></ul>',22)])])}const u=e(d,[["render",i]]);export{p as __pageData,u as default};
